void dfs(TreeNode* n, long long rem, vector<int>& path, vector<vector<int>>& out) {
    if (!n) return;
    path.push_back(n->val);
    rem -= n->val;
    if (!n->left && !n->right && rem == 0) out.push_back(path);
    dfs(n->left, rem, path, out);
    dfs(n->right, rem, path, out);
}

long long gain(TreeNode* n, long long& best) {
    if (!n) return 0;
    long long l = max(0LL, gain(n->left, best));
    long long r = max(0LL, gain(n->right, best));
    best = max(best, n->val + l + r);
    return n->val + l + r;
}
